#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    char *end1, *end2;
    long long a = strtol(argv[1], &end1, 10);
    long long b = strtol(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }
    long long abs_a = a < 0 ? -a : a;
    long long abs_b = b < 0 ? -b : b;
    if (abs_a > 1000000LL || abs_b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }
    long long g = gcd_ll(abs_a, abs_b);
    long long l = (abs_a / g) * abs_b;
    printf("gcd=%lld lcm=%lld\n", g, l);
    return 0;
}
